/// <summary>
/// Provides bulk cancellation of remaining physical quantities on open purchase order lines.
/// Invoked as an action menu item from the AAXPurchLineClose form, supports multi-select
/// to cancel remainders across many lines in a single operation.
/// Handles intercompany synchronization, Landed Cost (ITM) ship line updates,
/// and MCR Call Center order cancellation workflows.
/// </summary>
class AAXPurchLineClose
{
}

Method.Source:
/// <summary>
/// Constructs a new instance of the <c>AAXPurchLineClose</c> class.
/// </summary>
/// <returns>A new <c>AAXPurchLineClose</c> instance.</returns>
public static AAXPurchLineClose construct()
{
    return new AAXPurchLineClose();
}

/// <summary>
/// Entry point invoked by the AAXPurchLineClose action menu item.
/// Iterates over all selected records in the AAXPurchLineOpen form datasource
/// and cancels the remaining physical quantity on each corresponding PurchLine.
/// Refreshes the calling form after processing.
/// </summary>
/// <param name = "args">Framework arguments containing the caller form and selected records.</param>
public static void main(Args args)
{
    MultiSelectionHelper    multiSelectionHelper;
    AAXPurchLineOpen        AAXPurchLineOpen;
    FormDataSource          AAXPurchLineOpen_ds;
    AAXPurchLineClose       AAXPurchLineClose       =   AAXPurchLineClose::construct();

    FormRun                 callerForm;
    ;

    if (args && args.caller() && args.record())
    {
        multiSelectionHelper = MultiSelectionHelper::createFromCaller(args.caller());

        switch(args.record().TableId)
        {
            case tablenum(AAXPurchLineOpen) :
                AAXPurchLineOpen = args.record();
                AAXPurchLineOpen_ds = FormDataUtil::getFormDataSource(AAXPurchLineOpen);

                multiSelectionHelper.createQueryRanges(AAXPurchLineOpen_ds.queryBuildDataSource(), fieldstr(AAXPurchLineOpen, PurchId));

                AAXPurchLineOpen= multiSelectionHelper.getFirst();
                while (AAXPurchLineOpen)
                {
                    AAXPurchLineClose.runPurchLine(PurchLine::findRecId(AAXPurchLineOpen.PurchLineRecId,true));

                    AAXPurchLineOpen = multiSelectionHelper.getNext();
                }
                break;

        }

        callerForm = args.caller();
        callerForm.dataSource().research();
    }
}

/// <summary>
/// Cancels the remaining physical quantity on a single purchase order line.
/// Sets RemainPurchPhysical to zero, recalculates RemainInventPhysical,
/// synchronizes intercompany remaining quantities, writes the updated line,
/// and conditionally triggers a Landed Cost (ITM) ship line update via reflection.
/// Each line is processed in its own transaction; errors are caught and logged
/// as warnings so that other selected lines continue processing.
/// </summary>
/// <param name = "PurchLine">The PurchLine buffer to cancel, selected for update.</param>
public void runPurchLine(PurchLine PurchLine)
{
    InventQty       diffRemainPurchPhysical;
    InventQty       diffRemainInventPhysical;

    try
    {
        ttsbegin;

        diffRemainPurchPhysical = 0;
        diffRemainInventPhysical = PurchLine.calcQtyOrdered(diffRemainPurchPhysical);

        PurchLine.RemainPurchPhysical  = 0;
        PurchLine.RemainInventPhysical = PurchLine.calcQtyOrdered(PurchLine.RemainPurchPhysical);

        if (PurchLine.validateWrite() && PurchLine.purchTable().checkUpdate())
        {
            InterCompanyUpdateRemPhys::synchronize(
                    PurchLine,
                    diffRemainInventPhysical,
                    diffRemainPurchPhysical);

            PurchLine.write();

            if (diffRemainPurchPhysical)
            {
                SysDictClass  dictClass;
                Object        instance;

                dictClass = new SysDictClass(className2Id('PurchLine'));
                instance  = dictClass.makeObject();

                dictClass.callObject('ITMUpdateShipLine', instance, PurchLine, PurchLine.orig(), true);

                instance.write();
            }

        }

        ttscommit;
    }
    catch
    {
        warning(strFmt("@AAXPOCloseHelper:AAXPOCloseHelperCancelError", PurchLine.PurchId, PurchLine.LineNumber, PurchLine.ItemId, PurchLine.InventTransId));
    }
}

/// <summary>
/// Updates the remaining physical quantity on a purchase line with full intercompany
/// and MCR Call Center cancellation support. Synchronizes intercompany remaining
/// quantities, handles drop-shipment scenarios by zeroing all remaining fields,
/// writes the line, updates the purchase order back-order status, and processes
/// MCR sales order cancellations and payment adjustments.
/// </summary>
/// <param name = "_callerPurchLine">The PurchLine buffer to be updated with zeroed remaining quantities.</param>
protected void updateRemainPhysical(PurchLine _callerPurchLine)
{
    PurchLine       purchLineLocal = PurchLine::findRecId(_callerPurchLine.RecId);

    InventQty       diffRemainPurchPhysical       = purchLineLocal.RemainPurchPhysical;
    InventQty       diffRemainInventPhysical      = purchLineLocal.RemainInventPhysical;
    PdsCWInventQty  diffPdsCWRemainInventPhysical = purchLineLocal.PdsCWRemainInventPhysical;

    MCRSalesOrderCancellation mcrSalesOrderCancellation;
    mcrSalesOrderCancellation = this.mcrSalesOrderCancelInit(purchLineLocal.InventRefTransId);

    InterCompanyUpdateRemPhys::synchronize(_callerPurchLine,
                                            diffRemainInventPhysical,
                                            diffRemainPurchPhysical,
                                            InterCompanySkipUpdate::No,
                                            diffPdsCWRemainInventPhysical);

    if (_callerPurchLine.ItemRefType  == InventRefType::Sales
                && _callerPurchLine.InventRefTransId
                && _callerPurchLine.isDropShipment())
    {
        _callerPurchLine.reread();
        _callerPurchLine.RemainPurchPhysical         = 0;
        _callerPurchLine.RemainInventPhysical        = 0;
        _callerPurchLine.PdsCWRemainInventPhysical   = 0;
    }
    _callerPurchLine.write();

    _callerPurchLine.purchTable().updateBackStatus();

    this.mcrSalesOrderCancel(mcrSalesOrderCancellation, purchLineLocal.InventRefTransId);
}

/// <summary>
/// Initializes the MCR Call Center sales order cancellation process.
/// If the MCR Call Center configuration key is enabled and the purchase line
/// is linked to a sales line, creates an MCRSalesOrderCancellation instance
/// and captures the pre-cancellation state of the sales order.
/// </summary>
/// <param name = "_purchLineRefTransId">The inventory transaction ID linking the purchase line to a sales line.</param>
/// <returns>An initialized <c>MCRSalesOrderCancellation</c> object, or null if MCR is disabled or no linked sales line exists.</returns>
private MCRSalesOrderCancellation mcrSalesOrderCancelInit(TradeInventTransId _purchLineRefTransId)
{
    MCRSalesOrderCancellation MCRSalesOrderCancellation;

    if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
    {
        SalesLine salesLine = SalesLine::findInventTransId(_purchLineRefTransId, true);
        if (salesLine)
        {
            MCRSalesOrderCancellation = new MCRSalesOrderCancellation();
            MCRSalesOrderCancellation.preCancel(SalesTable::find(salesLine.SalesId));
        }
    }
    return MCRSalesOrderCancellation;
}

/// <summary>
/// Completes the MCR Call Center sales order cancellation workflow after a purchase
/// line remainder has been cancelled. If the linked sales line status has become Canceled,
/// posts the line-level cancellation. If the entire sales order is also Canceled,
/// posts the order-level cancellation. Always posts the cancellation payment adjustment
/// to handle any payment holds or refunds on the sales order.
/// </summary>
/// <param name = "_mcrSalesOrderCancellation">The MCR cancellation object initialized via <c>mcrSalesOrderCancelInit</c>.</param>
/// <param name = "_purchLineRefTransId">The inventory transaction ID linking to the sales line.</param>
private void mcrSalesOrderCancel(MCRSalesOrderCancellation _mcrSalesOrderCancellation, TradeInventTransId _purchLineRefTransId)
{
    if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
    {
        SalesLine salesLine = SalesLine::findInventTransId(_purchLineRefTransId,true);
        if (salesLine)
        {
            SalesTable salesTable = SalesTable::find(salesLine.SalesId, true);
            if (salesLine.SalesStatus == SalesStatus::Canceled)
            {
                SalesLine salesLineLocal = SalesLine::findRecId(salesLine.RecId);
                _mcrSalesOrderCancellation.postCancelLine(salesLineLocal);
                // Additional find in case the status changed in the postCancelLine method
                salesTable = SalesTable::find(salesLine.SalesId,true);

                if (salesTable.SalesStatus == SalesStatus::Canceled)
                {
                    _mcrSalesOrderCancellation.postCancelOrder(salesTable);
                }
            }

            // Additional find in case the status changed in the postCancelLine or postCancelOrder method
            salesTable = SalesTable::find(salesLine.SalesId, true);
            _mcrSalesOrderCancellation.postCancelAdjPayment(salesTable);
        }
    }
}
